165	export type SealedRecord = Readonly<Record<string, unknown>> & Readonly<{ digest: string }>;
166	
167	export function seal(body: Readonly<Record<string, unknown>>): SealedRecord {
168		return Object.freeze({ ...body, digest: sha256(canonical(body)) });
169	}
170	
171	export function verifySeal(record: SealedRecord): SealedRecord {
172		const { digest, ...body } = record;
173		const recomputed = sha256(canonical(body));
174		if (recomputed !== digest)
175			throw new Error(
176				`Angular jira-clone closure record digest differs: recorded ${digest}, recomputed ${recomputed}`,
177			);
178		return record;
179	}
180	
181	export function buildClosureRecord(input: {
182		manifest: string;
183		lockfile: string;
184		installExitStatus: number;
185		installStderrWarningKinds: readonly string[];
186		buildExitStatus: number;
187		buildErrorLines: readonly string[];
188		packagesAdded: number;
189	}): { closure: SealedRecord; acquisition: SealedRecord } {
190		const artifacts = acquiredArtifacts(input.lockfile);
191		const acquisition = seal({
192			schemaVersion: 'versionless.angular-jira-clone-acquired-closure.v1',
193			unit: UNIT,
194			consentId: CONSENT_ID,
195			meaning:
196				'Every artifact the migrated closure install acquired, with the URL it came from and the integrity digest the resolver committed to. Read back out of the lockfile the install wrote.',
197			networkMode: 'consented',
198			hosts: acquisitionHosts(artifacts),
199			count: artifacts.length,
200			artifacts,
201		});
202		const closure = seal({
203			schemaVersion: 'versionless.angular-jira-clone-migrated-closure.v1',
204			unit: UNIT,
205			consentId: CONSENT_ID,
206			result:
207				input.installExitStatus === 0
208					? input.buildExitStatus === 0
209						? 'closure-resolved-build-green'
210						: 'closure-resolved-build-red-itemised'
211					: 'closure-unresolved',
212			meaning:
213				'The migrated manifest the extended cell produces resolves and installs. The production build was then run once and is recorded as it happened: red, with every demand the compiler made itemised below. No source transform was attempted in this unit.',
214			supersedes: SUPERSEDES,
215			changeset: MIGRATION_RECORD_FILE,
216			cell: {
217				node: 'v16.20.2',
218				architecture: 'darwin-arm64, native — no translation layer',
219				npm: '8.19.4 (bundled with the runtime)',
220				builder: '@angular-devkit/build-angular:browser (Angular 16.2), the builder the absorption restored',
221				environment: { NG_CLI_ANALYTICS: 'false' },
222			},
223			acquisition: {
224				purpose: 'Install the declared Angular 16.2 dependency closure the migrated manifest asks for.',
225				consentId: CONSENT_ID,
226				networkMode: 'consented',
227				method:
228					'npm install --no-audit --no-fund (no lockfile carried over: the era lockfileVersion 2 pins the Angular 13 closure)',
229				outcome: input.installExitStatus === 0 ? 'succeeded' : 'failed',
230				exitStatus: input.installExitStatus,
231				packagesAdded: input.packagesAdded,
232				migratedManifestSha256: sha256(input.manifest),
233				lockfileSha256: sha256(input.lockfile),
234				artifactsAcquired: artifacts.length,
235				artifactRecord: ACQUISITION_RECORD_FILE,
236				hosts: acquisitionHosts(artifacts),
237				warningKinds: input.installStderrWarningKinds,
238				warningNote:
239					'The install emitted engine warnings only. npm was not run with engine-strict, so a package declaring a Node line this cell does not meet was installed with a warning rather than refused; each such package is a transitive dependency, not one this cell names.',
240			},
241			buildAttempt: {
242				command: 'npx ng build --configuration production',
243				runs: 1,
244				exitStatus: input.buildExitStatus,
245				outcome: input.buildExitStatus === 0 ? 'green' : 'red',
246				artifactsEmitted: 0,
247				demands: BUILD_DEMANDS,
248				observedErrorLines: input.buildErrorLines,
249				itemisationMeaning:
250					'This list is the product of this unit, not a defect report. Each demand is a transform the migrated source has not yet been given; deciding and applying them is the next unit’s work.',
251			},
252			notEstablished: NOT_ESTABLISHED,
253			recordedRisks: RECORDED_RISKS,
254		});
255		return { closure, acquisition };
256	}
257	
258	/** Error lines the build log carries, quoted rather than summarised. */
259	export function buildErrorLinesOf(log: string): readonly string[] {
260		return Object.freeze(
261			log
262				.split('\n')
263				.filter((line) => line.startsWith('Error:') || line.includes(' - Error: '))
264				.map((line) => (line.length > 400 ? `${line.slice(0, 400)}…` : line)),
265		);
266	}
267	
268	/** The distinct kinds of warning the install emitted, without their volume. */
269	export function warningKindsOf(log: string): readonly string[] {
270		const kinds = new Set<string>();
271		for (const line of log.split('\n')) {
272			const marker = line.startsWith('npm WARN ') ? line.slice(9).split(' ')[0] : undefined;
273			if (marker !== undefined && marker.length > 0) kinds.add(marker);
274		}
275		return Object.freeze([...kinds].sort());
276	}
277	
278	async function readNumberFrom(file: string, prefix: string): Promise<number> {
279		const text = await readFile(file, 'utf8');
280		const line = text.split('\n').find((entry) => entry.startsWith(prefix));
281		if (line === undefined) throw new Error(`Angular closure record: no "${prefix}" line in ${file}`);
282		const value = Number.parseInt(line.slice(prefix.length), 10);
283		if (Number.isNaN(value)) throw new Error(`Angular closure record: "${line}" is not a status`);
284		return value;
285	}
286	
287	function packagesAddedFrom(log: string): number {
288		for (const line of log.split('\n')) {
289			if (!line.startsWith('added ')) continue;
290			const value = Number.parseInt(line.slice(6).split(' ')[0] ?? '', 10);
291			if (!Number.isNaN(value)) return value;
292		}
293		throw new Error('Angular closure record: the install log records no package count');
294	}
295	
296	export async function main(): Promise<void> {
297		const read = async (name: string): Promise<string> =>
298			readFile(path.join(STAGE_DIRECTORY, name), 'utf8');
299		const installStdout = await read('install-1.stdout.log');
300		const records = buildClosureRecord({
301			manifest: await read('app/package.json'),
302			lockfile: await read('app/package-lock.json'),
303			installExitStatus: await readNumberFrom(path.join(STAGE_DIRECTORY, 'install-1.exit'), 'EXIT='),
304			installStderrWarningKinds: warningKindsOf(await read('install-1.stderr.log')),
305			buildExitStatus: await readNumberFrom(path.join(STAGE_DIRECTORY, 'build-1.exit'), 'EXIT='),
306			buildErrorLines: buildErrorLinesOf(await read('build-1.stderr.log')),
307			packagesAdded: packagesAddedFrom(installStdout),
308		});
309		await mkdir(evidenceDirectory, { recursive: true });
310		await writeFile(
311			path.join(evidenceDirectory, CLOSURE_RECORD_FILE),
312			canonical(verifySeal(records.closure)),
313		);
314		await writeFile(
315			path.join(evidenceDirectory, ACQUISITION_RECORD_FILE),
316			canonical(verifySeal(records.acquisition)),
317		);
318		process.stdout.write(
319			`closure: ${String(records.closure['result'])}; artifacts ${String(
320				(records.acquisition['count'] as number) ?? 0,
321			)}; demands ${String(BUILD_DEMANDS.length)}\n`,
322		);
323	}
324	
325	if (process.argv[1]?.endsWith('angular-jira-clone-closure-run.ts'))
326		main().catch((error: unknown) => {
327			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
328			process.exitCode = 1;
329		});
330

