16	import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
17	import * as path from 'pathe';
18	import {
19		ANGULAR_16_BROWSER_CELL,
20		migrateAngularCliEraWorkspace,
21		type AngularMigration,
22		type WorkspaceFile,
23	} from '../../../frameworks/angular/src/index.ts';
24	import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
25	
26	export const JIRA_CLONE_COMMIT = '059455b9933a236456524925065bce2c295e2d9a';
27	export const JIRA_CLONE_ARCHIVE_URL =
28		'https://codeload.github.com/trungvose/jira-clone-angular/tar.gz/059455b9933a236456524925065bce2c295e2d9a';
29	export const JIRA_CLONE_ARCHIVE_SHA256 =
30		'd913ad5d4686b6a236799166c7c781f624b3901a1826304e00c36eca82896bc5';
31	export const JIRA_CLONE_ARCHIVE_BYTES = 8048993;
32	
33	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
34	const evidenceDirectory = path.join(repositoryRoot, 'evidence/runs/angular-jira-clone');
35	
36	export const MIGRATION_RECORD_FILE = 'mj2-source-migration.json';
37	export const MIGRATION_UNIT = 'lrapr-t005/mj2-ecosystem-cell-closure';
38	export const CONSENT_ID = 'VL-LEGACY-CORPUS-2026-08-10';
39	
40	/**
41	 * The record this one replaces, and what changed between them.
42	 *
43	 * mj1 ran the same adapter over the same pinned tree before the target cell
44	 * carried an ecosystem table. Its changeset is still true about what it did;
45	 * it is superseded because the cell it applied was a smaller cell, and the
46	 * manifest it produced could not resolve.
47	 */
48	export const SUPERSEDES = Object.freeze({
49		record: 'mj1-source-migration.json',
50		unit: 'lrapr-t005/mj1-jira-clone-migration-lanes',
51		why: 'mj1 applied angular-16-browser-builder before the cell declared a community-library layer, so the community packages kept their era ranges and the closure the manifest asked for did not resolve. This record applies the same cell with that layer declared, and with the TSLint toolchain dropped as a declared difference. Every mj1 change is still in this changeset; the difference is additive.',
52	});
53	
54	/** Files the workspace may reference as a custom webpack fragment. */
55	export const CANDIDATE_WEBPACK_FRAGMENTS: readonly string[] = Object.freeze([
56		'webpack.config.js',
57		'extra-webpack.config.js',
58	]);
59	
60	async function typescriptModulesBelow(directory: string, root: string): Promise<WorkspaceFile[]> {
61		const files: WorkspaceFile[] = [];
62		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
63			left.name < right.name ? -1 : 1,
64		)) {
65			const item = path.join(directory, entry.name);
66			if (entry.isDirectory()) files.push(...(await typescriptModulesBelow(item, root)));
67			else if (entry.isFile() && path.extname(entry.name) === '.ts')
68				files.push({
69					path: path.relative(root, item).split(path.sep).join('/'),
70					source: await readFile(item, 'utf8'),
71				});
72		}
73		return files;
74	}
75	
76	async function readIfPresent(file: string, relative: string): Promise<WorkspaceFile | null> {
77		try {
78			return { path: relative, source: await readFile(file, 'utf8') };
79		} catch {
80			return null;
81		}
82	}
83	
84	/** Read the inputs the adapter migrates out of a materialised tree. */
85	export async function readWorkspace(tree: string): Promise<{
86		packageManifest: WorkspaceFile;
87		workspaceConfig: WorkspaceFile;
88		tsConfig: WorkspaceFile;
89		sourceModules: readonly WorkspaceFile[];
90		webpackFragments: readonly WorkspaceFile[];
91		workspaceFiles: readonly string[];
92	}> {
93		const read = async (relative: string): Promise<WorkspaceFile> => ({
94			path: relative,
95			source: await readFile(path.join(tree, relative), 'utf8'),
96		});
97		const fragments: WorkspaceFile[] = [];
98		for (const candidate of CANDIDATE_WEBPACK_FRAGMENTS) {
99			const found = await readIfPresent(path.join(tree, candidate), candidate);
100			if (found !== null) fragments.push(found);
101		}
102		return {
103			packageManifest: await read('package.json'),
104			workspaceConfig: await read('angular.json'),
105			tsConfig: await read('tsconfig.json'),
106			sourceModules: await typescriptModulesBelow(path.join(tree, 'src'), tree),
107			webpackFragments: fragments,
108			workspaceFiles: await workspacePathsBelow(tree, tree),
109		};
110	}
111	
112	/**
113	 * Every path the tree carries, workspace-relative, excluding the directories a
114	 * package manager or a build writes. The adapter is handed paths only; it reads
115	 * none of these files and removes one solely on what its name says it is.
116	 */
117	const UNWALKED_DIRECTORIES: readonly string[] = Object.freeze(['node_modules', 'dist', '.git']);
118	
119	async function workspacePathsBelow(directory: string, root: string): Promise<string[]> {
120		const paths: string[] = [];
121		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
122			left.name < right.name ? -1 : 1,
123		)) {
124			if (UNWALKED_DIRECTORIES.includes(entry.name)) continue;
125			const item = path.join(directory, entry.name);
126			if (entry.isDirectory()) paths.push(...(await workspacePathsBelow(item, root)));
127			else if (entry.isFile()) paths.push(path.relative(root, item).split(path.sep).join('/'));
