132	export type MigrationRecord = Readonly<Record<string, unknown>> & Readonly<{ digest: string }>;
133	
134	/**
135	 * What this cell reuses from the first Angular application, said plainly.
136	 *
137	 * The target cell is not a new one. `angular-16-browser-builder` was declared
138	 * for factoriolab and is adopted here unchanged, which is the point of a cell:
139	 * a second application either fits the declared cell or it does not. Reusing it
140	 * establishes nothing new about the cell itself.
141	 */
142	const CELL_REUSE: readonly string[] = Object.freeze([
143		'The target cell angular-16-browser-builder is the same cell factoriolab was migrated onto. It was not re-derived for this application and nothing here re-establishes its rationale.',
144		'Two facts about this application were added to the cell rather than to this fixture, because they are facts about the Angular ecosystem: the @angular-eslint family tracks the Angular major, and the official browser builder’s own postcss pipeline already runs tailwindcss, autoprefixer and `@import` resolution.',
145		'A third fact was added to the cell for this application and is a fact about the Angular ecosystem rather than about this application: the community library layer, read from registry.npmjs.org under this consent, as the versions each library published for the Angular 16 major. The table is keyed by package name and applies to any manifest; nothing in it names this application.',
146		'Both lanes of this cell run on Node 16.20.2, which is what this application’s own .nvmrc pins as a major and what the era baseline already used. The migrated lane therefore changes the framework without also changing the runtime.',
147	]);
148	
149	const NOT_ESTABLISHED: readonly string[] = Object.freeze([
150		'This record states what the adapter changed. Whether the changed tree installs and builds is recorded separately, in the build-lane records beside it, and neither is implied here.',
151		'No test-cell outcome is established: the karma/jasmine toolchain was aligned so the dependency closure could resolve, and no test run was attempted.',
152		'No browser behaviour, runtime parity or user-visible equivalence was observed. No witness ran.',
153	]);
154	
155	const NONCLAIMS: readonly string[] = Object.freeze([
156		'This record states which bytes a set of reusable transforms changed in one pinned tree. It establishes no migration feasibility, no production readiness, no certification and no support claim for Angular applications generally.',
157		'A second application on one adapter is a second application, not a general result. Nothing here says the adapter carries a third.',
158	]);
159	
160	export function buildMigrationRecord(
161		migration: AngularMigration,
162		unit: string,
163		consentId: string,
164	): MigrationRecord {
165		const body = {
166			schemaVersion: 'versionless.angular-jira-clone-source-migration.v2',
167			unit,
168			consentId,
169			result: 'source-migration-recorded',
170			supersedes: SUPERSEDES,
171			adapterApplication: 'second — the same @versionless/angular adapter, a different application',
172			source: {
173				repository: 'trungvose/jira-clone-angular',
174				commit: JIRA_CLONE_COMMIT,
175				archiveUrl: JIRA_CLONE_ARCHIVE_URL,
176				archiveSha256: JIRA_CLONE_ARCHIVE_SHA256,
177				bytes: JIRA_CLONE_ARCHIVE_BYTES,
178				era: 'Angular 13.2.4, CLI 13.2.5, @angular-builders/custom-webpack:browser over a root webpack.config.js, ng-zorro-antd 13, Akita 7, Tailwind 3, TypeScript 4.5.5',
179			},
180			cell: {
181				id: ANGULAR_16_BROWSER_CELL.id,
182				angularLine: ANGULAR_16_BROWSER_CELL.angularLine,
183				builder: ANGULAR_16_BROWSER_CELL.builder,
184				nodeLine: ANGULAR_16_BROWSER_CELL.nodeLine,
185				typescriptRange: ANGULAR_16_BROWSER_CELL.typescriptRange,
186				rationale: ANGULAR_16_BROWSER_CELL.rationale,
187				reuse: CELL_REUSE,
188			},
189			migration: {
190				applicationFilesScanned: migration.applicationFilesScanned,
191				applicationFilesChanged: migration.applicationFilesChanged,
192				workspaceFilesChanged: migration.workspaceFilesChanged,
193				files: migration.files
194					.filter((entry) => entry.changed)
195					.map((entry) => ({
196						path: entry.path,
197						kind: entry.kind,
198						sha256Before: entry.sha256Before,
199						sha256After: entry.sha256After,
200						changes: entry.changes,
201					})),
202				declaredDifferences: migration.declaredDifferences,
203				removedFiles: migration.removedFiles,
204			},
205			unhandled: migration.unhandled,
206			notEstablished: NOT_ESTABLISHED,
207			nonclaims: NONCLAIMS,
208		} as const;
209		return Object.freeze({ ...body, digest: sha256(canonical(body)) });
210	}
211	
212	/** Recompute the record's digest; a record that does not seal is rejected. */
213	export function verifyMigrationRecord(record: MigrationRecord): MigrationRecord {
214		const { digest, ...body } = record;
215		const recomputed = sha256(canonical(body));
216		if (recomputed !== digest)
217			throw new Error(
218				`Angular jira-clone migration record digest differs: recorded ${digest}, recomputed ${recomputed}`,
219			);
220		return record;
221	}
222	
223	export async function main(): Promise<void> {
224		const index = process.argv.indexOf('--tree');
225		const tree = index === -1 ? undefined : process.argv[index + 1];
226		if (tree === undefined)
227			throw new Error('Angular jira-clone migration requires --tree <materialised-tree>');
228		const workspace = await readWorkspace(tree);
229		const migration = migrateAngularCliEraWorkspace(workspace, ANGULAR_16_BROWSER_CELL);
230		const record = verifyMigrationRecord(
231			buildMigrationRecord(migration, MIGRATION_UNIT, CONSENT_ID),
232		);
233		const migratedTree = path.join(tree, '..', 'migrated');
234		for (const entry of migration.files) {
235			if (!entry.changed) continue;
236			const destination = path.join(migratedTree, entry.path);
237			await mkdir(path.dirname(destination), { recursive: true });
238			await writeFile(destination, entry.source);
239		}
240		await mkdir(evidenceDirectory, { recursive: true });
241		await writeFile(path.join(evidenceDirectory, MIGRATION_RECORD_FILE), canonical(record));
242		process.stdout.write(canonical(record));
243	}
244	
245	if (process.argv[1]?.endsWith('angular-jira-clone-migration-run.ts'))
246		main().catch((error: unknown) => {
247			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
248			process.exitCode = 1;
249		});
