340						builder = official;
341					}
342					if (
343						typeof builder === 'string' &&
344						isTslintBuilder(builder) &&
345						targetLineDropsTslint(cell)
346					) {
347						changes.push({ path: targetPath, from: builder, to: null });
348						for (const name of REMOVED_BUILDER_PACKAGES[builder] ?? [])
349							removedPackages.add(name);
350						declaredDifferences.push(tslintTargetRemoval(targetPath, builder, cell).reason);
351						continue;
352					}
353					if (typeof builder === 'string' && REMOVED_BUILDERS.includes(builder)) {
354						changes.push({ path: targetPath, from: builder, to: null });
355						for (const name of REMOVED_BUILDER_PACKAGES[builder] ?? [])
356							removedPackages.add(name);
357						unhandled.push(
358							`${targetPath} used ${builder}, which the ${cell.angularLine} devkit does not ship; ` +
359								'the target was removed and no replacement capability was chosen for it',
360						);
361						continue;
362					}
363					if (typeof builder === 'string' && !CARRIED_BUILDERS.includes(builder)) {
364						unhandled.push(
365							`${targetPath} uses ${builder}, which this capability does not recognise; ` +
366								'its options were left untouched',
367						);
368						migratedTargets[targetName] = targetValue;
369						continue;
370					}
371					if (target === null) {
372						migratedTargets[targetName] = targetValue;
373						continue;
374					}
375					const migratedTarget: JsonObject = { ...target, builder };
376					const options = objectAt(target['options']);
377					if (options !== null)
378						migratedTarget['options'] = migrateBuilderOptions(
379							options,
380							`${targetPath}.options`,
381							changes,
382							absorption.absorbed,
383						);
384					const configurations = objectAt(target['configurations']);
385					if (configurations !== null) {
386						const migratedConfigurations: JsonObject = {};
387						for (const [name, value] of Object.entries(configurations)) {
388							const configuration = objectAt(value);
389							migratedConfigurations[name] =
390								configuration === null
391									? value
392									: migrateBuilderOptions(
393											configuration,
394											`${targetPath}.configurations.${name}`,
395											changes,
396											absorption.absorbed,
397										);
398						}
399						migratedTarget['configurations'] = migratedConfigurations;
400					}
401					migratedTargets[targetName] = migratedTarget;
402				}
403				migratedProjects[projectName] = { ...project, [architectKey]: migratedTargets };
404			}
405			next['projects'] = migratedProjects;
406		}
407		return Object.freeze({
408			config: serialize(next),
409			changes: Object.freeze(changes),
410			removedPackages: Object.freeze([...removedPackages].sort(compareStrings)),
411			unhandled: Object.freeze(unhandled),
412			absorbedFragments: Object.freeze(absorption.absorbed ? absorption.analyses : []),
413			declaredDifferences: Object.freeze(declaredDifferences),
414		});
415	}
416	
417	export type TsConfigMigration = Readonly<{
418		config: string;
419		changes: readonly ConfigChange[];
420		unhandled: readonly string[];
421	}>;
422	
423	/**
424	 * Migrate a workspace `tsconfig.json` onto the declared cell.
425	 *
426	 * The Angular compiler on a modern line emits ES2022 output and requires
427	 * `useDefineForClassFields: false` at that target, because TypeScript's
428	 * standards-compliant class-field semantics would otherwise overwrite the
429	 * fields Angular's decorators initialise. `enableIvy` is removed: Ivy is the
430	 * only compiler left, and the option is no longer read.
431	 */
432	export function migrateAngularTsConfig(source: string, cell: AngularTargetCell): TsConfigMigration {
433		const config = parseStrictJson(source, 'tsconfig');
434		const changes: ConfigChange[] = [];
435		const unhandled: string[] = [];
436		const next: JsonObject = { ...config };
437		const compilerOptions = objectAt(config['compilerOptions']);
438		if (compilerOptions === null) {
439			unhandled.push('the tsconfig declares no compilerOptions; nothing was aligned');
440			return Object.freeze({
441				config: serialize(next),
442				changes: Object.freeze(changes),
443				unhandled: Object.freeze(unhandled),
444			});
445		}
446		const migrated: JsonObject = { ...compilerOptions };
447		for (const key of ['target', 'module'] as const) {
448			const from = compilerOptions[key];
449			if (from === 'ES2022') continue;
450			migrated[key] = 'ES2022';
451			changes.push({
452				path: `compilerOptions.${key}`,
453				from: from === undefined ? null : JSON.stringify(from),
454				to: '"ES2022"',
455			});
456		}
457		if (compilerOptions['useDefineForClassFields'] !== false) {
458			migrated['useDefineForClassFields'] = false;
459			changes.push({
460				path: 'compilerOptions.useDefineForClassFields',
461				from:
462					compilerOptions['useDefineForClassFields'] === undefined
463						? null
464						: JSON.stringify(compilerOptions['useDefineForClassFields']),
465				to: 'false',
466			});
467		}
468		next['compilerOptions'] = migrated;
469		const angularCompilerOptions = objectAt(config['angularCompilerOptions']);
470		if (angularCompilerOptions !== null && 'enableIvy' in angularCompilerOptions) {
471			const { enableIvy, ...rest } = angularCompilerOptions;
472			next['angularCompilerOptions'] = rest;
473			changes.push({
474				path: 'angularCompilerOptions.enableIvy',
475				from: JSON.stringify(enableIvy),
476				to: null,
477			});
478		}
479		unhandled.push(
480			`compilerOptions.lib was left as declared; the ${cell.angularLine} line does not require a specific lib set ` +
481				'and narrowing one could remove a type surface the application relies on',
482		);
483		return Object.freeze({
484			config: serialize(next),
485			changes: Object.freeze(changes),
486			unhandled: Object.freeze(unhandled),
487		});
488	}
